5	/**
6	 * Derives an owner's 'membershipPoints' and numeric 'membershipLevel', assigned
7	 * on create. Kept out of {@link OwnerMapper} so MapStruct does not mistake it for
8	 * an implicit property mapping method.
9	 */
10	public final class MembershipLevelResolver {
11	
12	    /** Points awarded when an email is present (non-blank). */
13	    private static final int EMAIL_POINTS = 2;
14	
15	    /** Points awarded when the owner's name was unique on create (namesakeCount is 0). */
16	    private static final int UNIQUE_NAME_POINTS = 1;
17	
18	    /** Points awarded for a household of three or more members. */
19	    private static final int HOUSEHOLD_POINTS = 2;
20	
21	    /** Points awarded for tenure over the threshold. */
22	    private static final int TENURE_POINTS = 3;
23	
24	    /** Elapsed fiscal years that must be exceeded before the tenure points are awarded. */
25	    private static final int TENURE_THRESHOLD_FISCAL_YEARS = 1;
26	
27	    /** A household of this many members (or more) earns the household points. */
28	    private static final int GOLD_HOUSEHOLD_SIZE = 3;
29	
30	    private MembershipLevelResolver() {
31	    }
32	
33	    /**
34	     * Returns the membership points for an owner. Starts at 0, gains 2 when an
35	     * email is present (non-blank), gains 1 when the owner's name was unique on
36	     * create ({@code namesakeCount} is 0), gains 2 when the owner belongs to a
37	     * household of three or more members and gains 3 for tenure over one elapsed
38	     * fiscal year.
39	     *
40	     * @param email                the owner's email, may be {@code null}
41	     * @param namesakeCount        the owner's namesake count, may be {@code null}
42	     * @param householdMemberCount the number of owners in the owner's household, may be {@code null}
43	     * @param registrationDate     the owner's registration date, may be {@code null}
44	     * @return the membership points, zero or more
45	     */
46	    public static int deriveMembershipPoints(String email, Integer namesakeCount,
47	            Integer householdMemberCount, LocalDate registrationDate) {
48	        int points = 0;
49	        if (email != null && !email.isBlank()) {
50	            points += EMAIL_POINTS;
51	        }
52	        if (namesakeCount != null && namesakeCount == 0) {
53	            points += UNIQUE_NAME_POINTS;
54	        }
55	        if (householdMemberCount != null && householdMemberCount >= GOLD_HOUSEHOLD_SIZE) {
56	            points += HOUSEHOLD_POINTS;
57	        }
58	        if (hasTenure(registrationDate)) {
59	            points += TENURE_POINTS;
60	        }
61	        return points;
62	    }
63	
64	    /**
65	     * Returns the membership level for an owner, mapped from its
66	     * {@link #deriveMembershipPoints membership points}: level 1 (0-1 points),
67	     * level 2 (2-3 points), level 3 (4-5 points) and level 4 (6 or more points).
68	     *
69	     * @param email                the owner's email, may be {@code null}
70	     * @param namesakeCount        the owner's namesake count, may be {@code null}
71	     * @param householdMemberCount the number of owners in the owner's household, may be {@code null}
72	     * @param registrationDate     the owner's registration date, may be {@code null}
73	     * @return the membership level, between 1 and 4 inclusive
74	     */
75	    public static int deriveMembershipLevel(String email, Integer namesakeCount,
76	            Integer householdMemberCount, LocalDate registrationDate) {
77	        int points = deriveMembershipPoints(email, namesakeCount, householdMemberCount, registrationDate);
78	        return levelForPoints(points);
79	    }
80	
81	    /**
82	     * Maps membership points to a membership level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more).
83	     *
84	     * @param points the owner's membership points
85	     * @return the membership level, between 1 and 4 inclusive
86	     */
87	    private static int levelForPoints(int points) {
88	        if (points >= 6) {
89	            return 4;
90	        }
91	        if (points >= 4) {
92	            return 3;
93	        }
94	        if (points >= 2) {
95	            return 2;
96	        }
97	        return 1;
98	    }
99	
100	    /**
101	     * Reports whether an owner's tenure exceeds the tenure threshold, i.e. more than one whole fiscal
102	     * year (see {@link FiscalYearResolver}) has elapsed between {@code registrationDate} and today. A
103	     * {@code null} or future registration date counts as no tenure.
104	     *
105	     * @param registrationDate the owner's registration date, may be {@code null}
106	     * @return {@code true} when more than one fiscal year has elapsed since registration
107	     */
108	    private static boolean hasTenure(LocalDate registrationDate) {
109	        if (registrationDate == null) {
110	            return false;
111	        }
112	        return FiscalYearResolver.elapsedFiscalYears(registrationDate, LocalDate.now())
113	            > TENURE_THRESHOLD_FISCAL_YEARS;
114	    }
115	}
